import ast
from fractions import Fraction

expressions = {
    "A": """not (not ((The capital of the Nigeria is Abuja.) and (max(-5, -1, -9, -3) - min(-5, -1, -9, -3) is greater than 4)) or ((False) and (10 * 1 + -4 * -6 is greater than -10 * 1))) and (not (not (-2 - (6 / 4) is less than or equal to 3) and (-9 * -8 <= 6)) or ((-5 - (2 / 10) > 5) or (max(3, 4, -5, -9) - min(3, 4, -5, -9) is greater than 1)))""",
    "B": """(not (not not not (not (not not not (not (not not ((not (-5 * -4 + 8 * 10 is greater than -1 * -3) or (max(-3, 1, -8, -8) - min(-3, 1, -8, -8) <= 5)) or (9 * -2 is less than or equal to -10)) or not not not (max(-6, 7, -7, -2) - min(-6, 7, -7, -2) is greater than 9)) and (5 * 9 + 7 * 7 is less than or equal to -2 * 1)) and not not (-5 * -2 > 9)) or (The capital of Armenia is Yerevan.)) and not not (1 * 7 > -10)) and (4 - (-3 / 2) <= -2)) or (max(6, -4, -3, -1) - min(6, -4, -3, -1) <= 7)""",
    "C": """not (not ((False) or (False)) and ((-3 * 1 <= -5) or (-2 * -8 + -7 * -4 is less than or equal to 6 * -2))) and (not (not (max(7, 8, -3, 1) - min(7, 8, -3, 1) <= 1) or (-10 * -6 + -7 * 7 is less than or equal to -9 * 10)) and (not (The capital of Iraq is Beirut.) or (-10 - (2 / -5) is less than or equal to 10)))""",
    "D": """not (((True) and (The capital of Iran is Tehran.)) or ((max(-10, -5, -10, -1) - min(-10, -5, -10, -1) <= 4) and (4 * -4 + 6 * -2 > -3 * -2))) and (not not (not not not (8 * 2 > 1) and not not (-7 - (-2 / 6) <= -8)) or not not not (not (True) and (False)))""",
    "E": """not not not (not not (not not not (not not (not (not (not not ((not (not not not (not (not (10 - (8 / -2) is greater than 2) and (2 * -1 + -2 * -3 is greater than -2 * 10)) and (The capital of Norway is Bergen.)) and not not (max(-10, -7, 8, 3) - min(-10, -7, 8, 3) <= 8)) or (1 * 10 > 1)) and (6 * -1 is less than or equal to 9)) or not not not (4 * -5 + 7 * -4 <= 3 * -1)) and (4 * -10 + -6 * 8 <= 2 * -8)) and (The capital of Canada is Toronto.)) or not not not (The capital of Gambia is Libreville.)) and not not (False)) or not not not (-4 - (-4 / 2) <= -5)) and not not (max(4, 6, 3, -9) - min(4, 6, 3, -9) is greater than 8)""",
}

# Explicit geographical premises: actual national capitals.
capitals = {
    "Nigeria": "Abuja",
    "Armenia": "Yerevan",
    "Iraq": "Baghdad",
    "Iran": "Tehran",
    "Norway": "Oslo",
    "Canada": "Ottawa",
    "Gambia": "Banjul",
}
claims = [
    ("The capital of the Nigeria is Abuja.", "Nigeria", "Abuja"),
    ("The capital of Armenia is Yerevan.", "Armenia", "Yerevan"),
    ("The capital of Iraq is Beirut.", "Iraq", "Beirut"),
    ("The capital of Iran is Tehran.", "Iran", "Tehran"),
    ("The capital of Norway is Bergen.", "Norway", "Bergen"),
    ("The capital of Canada is Toronto.", "Canada", "Toronto"),
    ("The capital of Gambia is Libreville.", "Gambia", "Libreville"),
]

# Interpret the small arithmetic/Boolean language directly, with exact division.
def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant) and type(node.value) in (int, bool):
        return node.value
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BoolOp):
        values = [evaluate(item) for item in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return Fraction(left) / Fraction(right)
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for operator, operand in zip(node.ops, node.comparators):
            right = evaluate(operand)
            if isinstance(operator, ast.Gt):
                results.append(left > right)
            elif isinstance(operator, ast.Lt):
                results.append(left < right)
            elif isinstance(operator, ast.LtE):
                results.append(left <= right)
            elif isinstance(operator, ast.GtE):
                results.append(left >= right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        if node.keywords:
            raise ValueError("Unexpected keyword argument")
        values = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(values)
        if node.func.id == "min":
            return min(values)
    raise ValueError("Unsupported syntax: " + ast.dump(node))

results = {}
try:
    for label, source in expressions.items():
        for phrase, country, claimed_capital in claims:
            source = source.replace(
                phrase, str(capitals[country] == claimed_capital)
            )
        source = source.replace("is less than or equal to", "<=")
        source = source.replace("is greater than", ">")
        results[label] = evaluate(ast.parse(source, mode="eval"))
        assert type(results[label]) is bool
except (SyntaxError, ValueError, TypeError, AssertionError) as error:
    print("UNSUPPORTED:", error)
    print("CHECK UNKNOWN")
else:
    for label, value in results.items():
        print(f"{label}: {value}")
    winners = [label for label, value in results.items() if value]
    print("True options:", ", ".join(winners) or "none")
    if len(winners) == 1:
        print("Expected answer:", winners[0])
        print("Submitted answer does not select the unique true option.")
        if results["C"] or results["E"]:
            print("Its elimination of C and E using false facts is invalid.")
        print("CHECK FAIL")
    else:
        print("The question's uniqueness premise is false.")
        print("CHECK FAIL")
